var n=`0175-ravioli-ricotta-e-spinaci`;var t=`world-0175`;var o=`IT`;var a=`southern-europe`;var g=4;var s=75;var l={en:`Ravioli Ricotta e Spinaci`,ua:`Равіолі з рикотою і шпинатом`};var r={en:`A classic dish from Italy, featuring chicken egg, ricotta, spinach, parmigiano reggiano. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: куряче яйце, рикота, шпинат, парміджано реджано. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var h=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 25 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 25 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:25,i:[[`all-purpose-flour`,420,`g`],[`chicken-egg`,4,`pcs`],[`table-salt`,4,`g`],[`extra-virgin-olive-oil`,15,`ml`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ricotta`,380,`g`],[`spinach`,340,`g`],[`parmigiano-reggiano`,95,`g`],[`ground-nutmeg`,2,`g`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:30,i:[]},{en:`Cook dumplings in batches in gently boiling salted water for about 5 minutes, until they float and the filling is cooked through. Lift out with a slotted spoon.`,ua:`Варіть вироби порціями в ледь киплячій підсоленій воді приблизно 5 хвилин, доки вони спливуть і начинка приготується. Вийміть шумівкою.`,t:[`boiling`],m:5,i:[[`water`,1600,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,70,`g`],[`sage`,15,`g`]]}];var u={slug:n,id:t,country:`IT`,region:a,servings:4,minutes:75,title:l,text:r,steps:h};export{o as country,u as default,t as id,s as minutes,a as region,g as servings,n as slug,h as steps,r as text,l as title};